const secret = $env.MOBILE_WEBHOOK_SECRET || 'changeme';
const hdr = $input.first().json.headers || {};
const got = hdr['x-webhook-secret'] || hdr['X-Webhook-Secret'];
if (secret !== 'changeme' && got !== secret) throw new Error('Invalid webhook secret');
const body = $input.first().json.body || $input.first().json;
return [{ json: {
  from: body.from || 'Unknown',
  channel: body.channel || 'message',
  body: body.body || body.text || '',
  verify_mode: body.verify_mode || 'approve'
}}];
